import { beforeEach, describe, expect, it, vi } from 'vitest'
import request from 'supertest'
import bcrypt from 'bcryptjs'

// Evaluate the actual predicates generated by HTTP handlers and the retrieval
// pipeline against distinct tenant fixtures. This is an in-memory Mongo subset,
// not an Atlas integration test; unsupported operators deliberately throw.
function matches(row: any, query: any): boolean {
  return Object.entries(query).every(([key, wanted]: [string, any]) => {
    if (key === '$or') return wanted.some((q: any) => matches(row, q))
    if (key === '$and') return wanted.every((q: any) => matches(row, q))
    const actual = key.split('.').reduce((r: any, part) => r?.[part], row)
    if (wanted === null) return actual == null
    if (wanted instanceof Date) return +actual === +wanted
    if (typeof wanted !== 'object') return String(actual) === String(wanted)
    return Object.entries(wanted).every(([operator, value]: [string, any]) => {
      if (operator === '$in') return value.includes(actual)
      if (operator === '$ne') return actual !== value
      if (operator === '$gt') return actual > value
      if (operator === '$gte') return actual >= value
      if (operator === '$elemMatch') return actual?.some((entry: any) => matches(entry, value)) ?? false
      throw new Error(`Unimplemented test operator ${operator}`)
    })
  })
}
function query(value: any) {
  return { sort: () => query(value), select: () => query(value), lean: async () => value,
    then: (resolve: any, reject: any) => Promise.resolve(value).then(resolve, reject) }
}
const state = vi.hoisted(() => ({ docs: [] as any[], chunks: [] as any[], conversations: [] as any[], messages: [] as any[], users: [] as any[], generated: [] as string[] }))
vi.mock('../src/models/Document.js', () => ({ DocumentModel: {
  find: (q: any) => query(state.docs.filter(row => matches(row, q))),
  findOne: (q: any) => query(state.docs.find(row => matches(row, q)) ?? null),
} }))
vi.mock('../src/models/Chunk.js', () => ({ ChunkModel: {
  find: (q: any) => query(state.chunks.filter(row => matches(row, q))),
  deleteMany: async (q: any) => { state.chunks = state.chunks.filter(row => !matches(row, q)) },
  aggregate: async (pipeline: any[]) => {
    let rows: any[] = state.chunks
    for (const stage of pipeline) {
      if (stage.$vectorSearch) rows = rows.filter(row => matches({ ...row, scopeKey: row.indexedScope ?? row.scopeKey }, stage.$vectorSearch.filter)).slice(0, stage.$vectorSearch.limit)
      else if (stage.$lookup) rows = rows.map(row => ({ ...row, score: 1, document: state.docs.filter(doc => doc._id === row.documentId) }))
      else if (stage.$match) rows = rows.filter(row => matches(row, stage.$match))
      else if (!stage.$project) throw new Error('Unknown aggregation stage in test')
    }
    return rows
  },
} }))
vi.mock('../src/models/Conversation.js', () => ({ ConversationModel: {
  find: (q: any) => query(state.conversations.filter(row => matches(row, q))),
  findOne: (q: any) => query(state.conversations.find(row => matches(row, q)) ?? null),
  create: async (row: any) => { const result = { _id: '900000000000000000000001', ...row }; state.conversations.push(result); return result },
  findByIdAndUpdate: async () => null,
} }))
vi.mock('../src/models/Message.js', () => ({ MessageModel: {
  find: (q: any) => query(state.messages.filter(row => matches(row, q))),
  create: async (row: any) => { const result = { _id: String(state.messages.length), ...row }; state.messages.push(result); return result },
  deleteMany: async (q: any) => { state.messages = state.messages.filter(row => !matches(row, q)) },
} }))
vi.mock('../src/models/User.js', () => ({ UserModel: { findOne: async (q: any) => state.users.find(row => matches(row, q)) ?? null, create: async (row: any) => ({ _id: 'fake-created-user', ...row }) } }))
vi.mock('../src/models/Bootstrap.js', () => ({ ADMIN_CLAIM_ID: 'test-admin-claim', BootstrapModel: { create: async () => ({}), deleteOne: async () => ({}) } }))
vi.mock('../src/documents/ingest.js', () => ({ ingestDocument: vi.fn() }))
vi.mock('../src/config/rateLimit.js', () => {
  const pass = (_req: any, _res: any, next: any) => next()
  return { chatRateLimiter: pass, uploadRateLimiter: pass, demoLoginRateLimiter: pass, authRateLimiter: pass }
})
vi.mock('../src/rag/provider.js', () => ({
  isRateLimitError: () => false,
  getEmbeddingProvider: () => ({ embedOne: async () => [1] }),
  getLlmProvider: () => ({ generate: async (prompt: string) => { state.generated.push(prompt); return prompt } }),
}))
import { createApp } from '../src/app.js'
import { signToken } from '../src/auth/jwt.js'
import { retrieve } from '../src/rag/retriever.js'
import { buildRetrievalScope } from '../src/documents/scope.js'

const userA = { userId: '100000000000000000000001', role: 'user' as const }
const userB = { userId: '100000000000000000000002', role: 'user' as const }
const demoA = { userId: '100000000000000000000003', role: 'user' as const, demoSessionId: 'demo-a' }
const demoB = { ...demoA, demoSessionId: 'demo-b' }
const docId = (n: number) => `20000000000000000000000${n}`
const convoId = (n: number) => `30000000000000000000000${n}`
const authorization = (user: typeof userA) => `Bearer ${signToken(user)}`
function addDoc(n: number, owner: typeof demoA | typeof userA, content: string, age = 0) {
  const session = 'demoSessionId' in owner ? owner.demoSessionId : null
  const doc = { _id: docId(n), filename: `${content}.txt`, uploadedBy: owner.userId, scopeKey: session ?? owner.userId,
    demoSessionId: session, isSeed: false, status: 'ready', createdAt: new Date(Date.now() - age),
    deleteOne: async () => { state.docs = state.docs.filter(row => row._id !== docId(n)) } }
  state.docs.push(doc)
  state.chunks.push({ _id: `chunk-${n}`, documentId: doc._id, scopeKey: doc.scopeKey, content })
}
function addConversation(n: number, owner: typeof demoA | typeof userA, age = 0) {
  state.conversations.push({ _id: convoId(n), userId: owner.userId, demoSessionId: 'demoSessionId' in owner ? owner.demoSessionId : null,
    title: `conversation-${n}`, createdAt: new Date(Date.now() - age),
    deleteOne: async () => { state.conversations = state.conversations.filter(row => row._id !== convoId(n)) } })
  state.messages.push({ _id: `message-${n}`, conversationId: convoId(n), role: 'user', content: `secret-message-${n}` })
}
beforeEach(() => {
  state.docs = []; state.chunks = []; state.conversations = []; state.messages = []; state.generated = []; state.users = []
  addDoc(1, userA, 'USER_A'); addDoc(2, userB, 'USER_B')
  addDoc(3, demoA, 'DEMO_A'); addDoc(4, demoB, 'DEMO_B')
  addDoc(5, demoA, 'EXPIRED_DEMO', 3 * 60 * 60 * 1000)
  state.docs.push({ _id: docId(6), filename: 'SEED.txt', scopeKey: 'demo-seed', demoSessionId: null, isSeed: true, status: 'ready', createdAt: new Date(0) })
  state.chunks.push({ _id: 'chunk-6', documentId: docId(6), scopeKey: 'demo-seed', content: 'SEED' })
  addConversation(1, userA); addConversation(2, userB); addConversation(3, demoA); addConversation(4, demoB)
  addConversation(5, demoA, 3 * 60 * 60 * 1000)
})

describe.each([{ name: 'registered users', a: userA, own: 1, other: 2, expected: ['USER_A'] }, { name: 'demo sessions', a: demoA, own: 3, other: 4, expected: ['DEMO_A', 'SEED'] }])('$name HTTP isolation', ({ a, own, other, expected }) => {
  it('lists and previews only allowed documents', async () => {
    const app = createApp()
    const list = await request(app).get('/api/documents').set('Authorization', authorization(a))
    expect(list.status).toBe(200)
    expect(list.body.map((d: any) => d.filename).sort()).toEqual(expected.map(x => `${x}.txt`).sort())
    const ownPreview = await request(app).get(`/api/documents/${docId(own)}/preview`).set('Authorization', authorization(a))
    expect(ownPreview.status).toBe(200)
    expect(ownPreview.body.text).toContain(expected[0])
    for (const route of ['status', 'preview']) {
      const forbidden = await request(app).get(`/api/documents/${docId(other)}/${route}`).set('Authorization', authorization(a))
      expect(forbidden.status).toBe(404)
    }
    const deletion = await request(app).delete(`/api/documents/${docId(other)}`).set('Authorization', authorization(a))
    expect(deletion.status).toBe(404)
    expect(state.docs.some(d => d._id === docId(other))).toBe(true)
  })
  it('enforces the same scopes in vector search and actual chat orchestration', async () => {
    const chunks = await retrieve('tell me secrets', { scopeKeys: buildRetrievalScope(a) })
    expect(chunks.map(c => c.content).sort()).toEqual([...expected].sort())
    const result = await request(createApp()).post('/api/conversations/chat').set('Authorization', authorization(a)).send({ question: 'tell me secrets' })
    expect(result.status).toBe(200)
    expect(result.body.message.sources.map((s: any) => s.filename).sort()).toEqual(expected.map(x => `${x}.txt`).sort())
    expect(state.generated.join(' ')).not.toMatch(/USER_B|DEMO_B|EXPIRED_DEMO/)
  })
  it('denies another owner conversation read, chat continuation and deletion', async () => {
    const app = createApp()
    const list = await request(app).get('/api/conversations').set('Authorization', authorization(a))
    expect(list.body.map((c: any) => c.id)).toEqual([convoId(own)])
    expect((await request(app).get(`/api/conversations/${convoId(own)}`).set('Authorization', authorization(a))).status).toBe(200)
    expect((await request(app).get(`/api/conversations/${convoId(other)}`).set('Authorization', authorization(a))).status).toBe(404)
    expect((await request(app).delete(`/api/conversations/${convoId(other)}`).set('Authorization', authorization(a))).status).toBe(404)
    const continuation = await request(app).post('/api/conversations/chat').set('Authorization', authorization(a)).send({ question: 'tell me secrets', conversationId: convoId(other) })
    expect(continuation.status).toBe(404)
    expect(state.generated).toHaveLength(0)
    expect(state.messages.some(m => m.conversationId === convoId(other))).toBe(true)
  })
})
it('rejects expired demo direct document and conversation reads before cleanup', async () => {
  const app = createApp()
  for (const suffix of ['status', 'preview']) expect((await request(app).get(`/api/documents/${docId(5)}/${suffix}`).set('Authorization', authorization(demoA))).status).toBe(404)
  expect((await request(app).get(`/api/conversations/${convoId(5)}`).set('Authorization', authorization(demoA))).status).toBe(404)
})
it('refuses ordinary password login for the shared demo identity', async () => {
  state.users.push({ _id: demoA.userId, email: 'demo@docuchat.app', isDemo: true, role: 'user', passwordHash: await bcrypt.hash('known-demo-password', 4) })
  const result = await request(createApp()).post('/api/auth/login').send({ email: 'demo@docuchat.app', password: 'known-demo-password' })
  expect(result.status).toBe(401)
  expect(result.body.token).toBeUndefined()
})
it.each([{ question: {} }, { question: 'x'.repeat(4001) }, { question: 'hi', conversationId: { $ne: null } }, { question: 'hi', conversationId: 'bad-id' }])('rejects invalid chat before generation: %j', async body => {
  const result = await request(createApp()).post('/api/conversations/chat').set('Authorization', authorization(userA)).send(body)
  expect(result.status).toBe(400)
  expect(state.generated).toHaveLength(0)
})
it('filters stale, differently scoped and failed vector parents before calling the model', async () => {
  state.chunks.push({ _id: 'mismatched', documentId: docId(2), scopeKey: userA.userId, content: 'B_PRIVATE_STALE' })
  state.chunks.push({ _id: 'orphan', documentId: 'missing', scopeKey: userA.userId, content: 'DELETED_PRIVATE' })
  addDoc(7, userA, 'FAILED_PRIVATE')
  state.docs.find(doc => doc._id === docId(7)).status = 'error'
  const result = await request(createApp()).post('/api/conversations/chat').set('Authorization', authorization(userA)).send({ question: 'what is here?' })
  expect(result.status).toBe(200)
  expect(result.body.message.sources.map((source: any) => source.filename)).toEqual(['USER_A.txt'])
  expect(state.generated.join(' ')).not.toMatch(/B_PRIVATE_STALE|DELETED_PRIVATE|FAILED_PRIVATE/)
})
it('permits deleting an owned document and conversation, while keeping B intact', async () => {
  const app = createApp()
  expect((await request(app).delete(`/api/documents/${docId(1)}`).set('Authorization', authorization(userA))).status).toBe(200)
  expect((await request(app).delete(`/api/conversations/${convoId(1)}`).set('Authorization', authorization(userA))).status).toBe(200)
  expect(state.docs.some(doc => doc._id === docId(1))).toBe(false)
  expect(state.chunks.some(chunk => chunk.documentId === docId(1))).toBe(false)
  expect(state.messages.some(message => message.conversationId === convoId(1))).toBe(false)
  expect(state.docs.some(doc => doc._id === docId(2))).toBe(true)
  expect(state.messages.some(message => message.conversationId === convoId(2))).toBe(true)
})
it('rejects expired demo continuation and deletion while leaving cleanup responsible for storage', async () => {
  const app = createApp()
  const token = authorization(demoA)
  expect((await request(app).post('/api/conversations/chat').set('Authorization', token).send({ question: 'continue', conversationId: convoId(5) })).status).toBe(404)
  expect((await request(app).delete(`/api/conversations/${convoId(5)}`).set('Authorization', token)).status).toBe(404)
  expect((await request(app).delete(`/api/documents/${docId(5)}`).set('Authorization', token)).status).toBe(404)
  expect(state.generated).toHaveLength(0)
})
it('accepts a real registered-user password login', async () => {
  state.users.push({ _id: userA.userId, email: 'a@example.test', isDemo: false, role: 'user', passwordHash: await bcrypt.hash('fake-user-password', 4) })
  const result = await request(createApp()).post('/api/auth/login').send({ email: 'a@example.test', password: 'fake-user-password' })
  expect(result.status).toBe(200)
  expect(typeof result.body.token).toBe('string')
})
it('does not preview a chunk that disagrees with the authorized parent scope', async () => {
  state.chunks.push({ _id: 'wrong-scope', documentId: docId(1), scopeKey: userB.userId, content: 'B_PRIVATE_MISMATCHED' })
  const result = await request(createApp()).get(`/api/documents/${docId(1)}/preview`).set('Authorization', authorization(userA))
  expect(result.status).toBe(200)
  expect(result.body.text).toContain('USER_A')
  expect(result.body.text).not.toContain('B_PRIVATE_MISMATCHED')
})

it.each([
  { email: {}, password: 'fake-password' },
  { email: 'invalid-address', password: 'fake-password' },
  { email: 'a@example.test', password: {} },
  { email: 'a@example.test', password: 'x'.repeat(73) },
])('rejects malformed authentication input before account work: %j', async body => {
  for (const endpoint of ['register', 'login']) {
    const result = await request(createApp()).post(`/api/auth/${endpoint}`).send(body)
    expect(result.status).toBe(400)
    expect(result.body.token).toBeUndefined()
  }
})
it('keeps seed documents read-only for demos and hidden from registered users', async () => {
  const app = createApp()
  expect((await request(app).get(`/api/documents/${docId(6)}/preview`).set('Authorization', authorization(demoA))).status).toBe(200)
  expect((await request(app).delete(`/api/documents/${docId(6)}`).set('Authorization', authorization(demoA))).status).toBe(404)
  expect((await request(app).get(`/api/documents/${docId(6)}/preview`).set('Authorization', authorization(userA))).status).toBe(404)
  expect((await request(app).get(`/api/documents/${docId(1)}/preview`).set('Authorization', authorization(demoA))).status).toBe(404)
  expect(state.docs.some(doc => doc._id === docId(6))).toBe(true)
})
it('cannot expose demo conversations through a legacy sessionless shared-user token', async () => {
  const app = createApp()
  const token = authorization({ userId: demoA.userId, role: 'user' })
  const result = await request(app).get('/api/conversations').set('Authorization', token)
  expect(result.status).toBe(200)
  expect(result.body).toEqual([])
  expect((await request(app).get(`/api/conversations/${convoId(3)}`).set('Authorization', token)).status).toBe(404)
})

it('rechecks current chunk ownership after an eventually stale vector prefilter', async () => {
  state.chunks.push({ _id: 'stale-index', documentId: docId(1), scopeKey: userB.userId, indexedScope: userA.userId, content: 'B_PRIVATE_STALE_INDEX' })
  const result = await request(createApp()).post('/api/conversations/chat').set('Authorization', authorization(userA)).send({ question: 'what is here?' })
  expect(result.status).toBe(200)
  expect(state.generated.join(' ')).not.toContain('B_PRIVATE_STALE_INDEX')
  expect(result.body.message.sources.map((source: any) => source.chunkId)).toEqual(['chunk-1'])
})
